const knownMedicines = [
  ...medicines.map(({id,name,ingredients}) => ({id,name,ingredients})),
  ...interactions.companions
];
const genericById = new Map(knownMedicines.map(medicine => [medicine.id,medicine]));
export const guidanceMedicine = (id: string | null) => id ? genericById.get(id) : undefined;

function key(name: string) {return name.trim().toLowerCase().replace(/\s+/g,' ');}

export function matchTypedMedicine(input: string): string | null {
  const name=key(input);
  const record=knownMedicines.find(medicine=>key(medicine.name)===name);
  if(record)return record.id;
  const ingredients=name.split(/\s*\+\s*|\s+and\s+/);
  if(ingredients.length>1)return matchIngredients(ingredients)?.id??null;
  const ingredient=matchIngredient(name);
  if(ingredient)return ingredient.id;
  const products=nigeriaProducts.filter(product=>[key(product.name),key(product.number),key(product.name.split(' ')[0])].includes(name));
  const productIds=[...new Set(products.map(product=>product.medicineId))];
  return productIds.length===1?productIds[0]:null;
}

export function findOtherMedicines(input:string){
  const query=key(input);
  if(query.length<2)return [];
  const productMatches=new Set(nigeriaProducts.filter(product=>
    [key(product.name),key(product.number)].some(value=>value.includes(query))).map(product=>product.medicineId));
  return knownMedicines.filter(medicine=>productMatches.has(medicine.id)||
    [medicine.name,...medicine.ingredients].some(value=>key(value).includes(query))).slice(0,5);
}

function editDistance(left: string, right: string) {
  let previous=Array.from({length:right.length+1},(_,index)=>index);
  for(let i=1;i<=left.length;i++){
    const current=[i];
    for(let j=1;j<=right.length;j++){
      current[j]=Math.min(previous[j]+1,current[j-1]+1,previous[j-1]+Number(left[i-1]!==right[j-1]));
    }
    previous=current;
  }
  return previous[right.length];
}

export function spellingCandidates(input: string) {
  const name=key(input);
  if(!/^[a-z]{5,40}$/.test(name))return [];
  const candidates=new Map<string,number>();
  const labels=[
    ...knownMedicines.filter(medicine=>medicine.ingredients.length===1).map(({id,name})=>({id,name})),
    ...nigeriaProducts.map(product=>({id:product.medicineId,name:product.name.split(' ')[0]}))
  ];
  for(const label of labels){
    const distance=editDistance(name,key(label.name));
    if(distance>0&&distance<=(name.length>=8?2:1))candidates.set(label.id,Math.min(candidates.get(label.id)??Infinity,distance));
  }
  return [...candidates].sort((a,b)=>a[1]-b[1]).slice(0,5).map(([id,distance])=>({id,distance}));
}

export function parseGuidanceContext(body: unknown): GuidanceContext | null {
  if(!body||typeof body!=='object'||Array.isArray(body))return null;
  const {medicineId,reason,prescribed,otherMedicines,namesIncomplete}=body as Record<string,unknown>;
  if(typeof medicineId!=='string'||!medicines.some(medicine=>medicine.id===medicineId)||
    typeof reason!=='string'||reason.length>500||typeof prescribed!=='boolean'||typeof namesIncomplete!=='boolean'||
    !Array.isArray(otherMedicines)||otherMedicines.length>24)return null;
  const entries:OtherMedicine[]=[];
  for(const entry of otherMedicines){
    if(!entry||typeof entry.name!=='string'||!entry.name.trim()||entry.name.length>500||
      (entry.choice!==null&&(typeof entry.choice!=='string'||!guidanceMedicine(entry.choice))))return null;
    entries.push({name:entry.name.trim(),choice:entry.choice??matchTypedMedicine(entry.name)});
  }
  return {medicineId,reason:reason.trim(),prescribed,otherMedicines:entries,namesIncomplete};
}

function passage(id: PassageId): Evidence {
  const item=getPassage(id);
  return {id,title:item.title,text:item.text,source:item.reference};
}

const reasonEvidence: Partial<Record<ReturnType<typeof suggestReasons>[number],PassageId>>={
  throat:'tonsillitis_assessment', typhoid:'typhoid_assessment', urine:'uti_assessment', skin:'wound_assessment',boil:'boil',diarrhoea:'diarrhoea_assessment'
};
const backgroundByReason: Partial<Record<ReturnType<typeof suggestReasons>[number],PassageId>>={
    cough:'cough_aware',fever:'fever_ncdc',dental:'tooth_pain_aware'
};

// Search these vetted passages by meaning when the user’s wording differs from the known phrases.
const searchableReasonPassages=[
 ...Object.values(reasonEvidence),...Object.values(backgroundByReason),'surgical_wound_discharge'
] as const;

const reasonLabels:Record<ReturnType<typeof suggestReasons>[number],string>={
  cold:'cold or flu symptoms',throat:'sore throat',cough:'cough',fever:'fever',typhoid:'suspected typhoid',
  diarrhoea:'diarrhoea',urine:'pain when passing urine',skin:'a wound',boil:'a boil',
  dental:'tooth pain',headache:'headache',pain:'other pain'
};
const whoSafety={name:'WHO · 5 Moments for Medication Safety',url:'https://www.who.int/publications/i/item/WHO-HIS-SDS-2019.6'};

export function evidenceForCheck(medicine: Medicine, context: GuidanceContext) {
  const productSource={name:medicine.sourceLabel,url:medicine.source};
  const topics=suggestReasons(context.reason);
  const uncoveredReasons:string[]=[];
  const relevant=topics.flatMap((reason):Evidence[]=>{
    if(!medicine.antibiotic)return [];
    if(reason==='cold')return [{id:'cold-use',title:scenarios.cold.title,text:scenarios.cold.text,source:sources[0]}];
    const id=reasonEvidence[reason];
    if(id)return [passage(id)];
    uncoveredReasons.push(reasonLabels[reason]);
    return [];
  });
  const backgroundPassages=medicine.antibiotic?topics.flatMap(reason=>{
    const id=backgroundByReason[reason];
    return id?[passage(id)]:[];
  }):[];
  if(medicine.id==='ampicillin-cloxacillin'&&isWhiteScarDischarge(context.reason)&&!relevant.some(item=>item.id==='wound_assessment'))
    backgroundPassages.unshift(passage('wound_assessment'));
  const reasonSearch=medicine.antibiotic&&context.reason.trim()?searchableReasonPassages.map(passage):[];
  const medicineUses:Evidence[]=
    medicine.id==='ampicillin-cloxacillin'?[{
      id:'medicine-uses',title:'What ampicillin + cloxacillin treats',text:medicine.summary,
      source:{...productSource,name:productSource.name+' · section 4.1'}
    }]:[];
  const selection=[
    ...backgroundPassages,
    ...relevant,
    {id:'label-caution',title:'What to check on the label',text:medicine.caution,source:productSource},
    ...(context.otherMedicines.length||context.namesIncomplete?[{
      id:'other-medicines',title:'Ask about your other medicines',
      text:'Show your medicine list to a pharmacist. Ask what could change if you add this medicine.',source:whoSafety
    }]:[]),
    ...(medicine.antibiotic?[passage(context.prescribed?'prescription':'need')]:[])
  ];
  if(!medicine.antibiotic&&context.reason)selection.push({
    id:'reason-to-discuss',title:'Discuss why you want to take it',
    text:'Tell a pharmacist why you want to take this medicine. Ask what it is meant to help with.',source:whoSafety
  });
  if(!medicine.antibiotic&&context.prescribed)selection.push({
    id:'prescription-to-discuss',title:'Check the prescription instructions',
    text:'Ask your prescriber or pharmacist to explain any instructions you are unsure about.',source:whoSafety
  });
  return {
    candidates:[...new Map([...selection,...medicineUses,...reasonSearch].map(item=>[item.id,item])).values()],
    reasonSearchIds:reasonSearch.map(item=>item.id),fallback:selection.slice(0,Math.max(3,relevant.length+backgroundPassages.length)),reasonPassages:relevant,backgroundPassages,uncoveredReasons,
    needsReasonReview:(!context.prescribed||medicine.antibiotic)&&(!relevant.length||uncoveredReasons.length>0)
  };
}

export function interactionEvidence(medicine: Medicine, entries: readonly OtherMedicine[], namesIncomplete: boolean) {
  const pairs=new Set<string>();
  const findings:Evidence[]=[];
  let uncovered=namesIncomplete;
  for(const entry of entries){
    const companion=guidanceMedicine(entry.choice);
    const documents=companion?interactions.pairs.filter(({ingredients:[first,second]})=>
      (first.every(name=>medicine.ingredients.includes(name))&&second.every(name=>companion.ingredients.includes(name)))||
      (second.every(name=>medicine.ingredients.includes(name))&&first.every(name=>companion.ingredients.includes(name)))
    ):[];
    if(!documents.length)uncovered=true;
    for(const item of documents){
      if(pairs.has(item.id))continue;
      pairs.add(item.id);
      findings.push({id:item.id,title:item.title,text:item.text,source:item.source});
    }
  }
  return {interactions:findings,needsInteractionReview:uncovered};
}

export function localGuidance(medicine: Medicine, context: GuidanceContext): CheckGuidance {
  const {fallback:passages,needsReasonReview,uncoveredReasons}=evidenceForCheck(medicine,context);
  return {passages,needsReasonReview,uncoveredReasons,...interactionEvidence(medicine,context.otherMedicines,context.namesIncomplete),
    corrections:[],suggestions:[],source:'sources'};
}

export function validateGuidanceSelection(raw: string, passageIds: readonly string[], options: MatchSuggestions) {
  const response=JSON.parse(raw);
  if(!response||Array.isArray(response)||Object.keys(response).sort().join(',')!=='matches,passageIds'||
    !Array.isArray(response.passageIds)||response.passageIds.length<1||response.passageIds.length>3||
    new Set(response.passageIds).size!==response.passageIds.length||
    !response.passageIds.every((id:unknown)=>typeof id==='string'&&passageIds.includes(id))||
    !Array.isArray(response.matches))throw new Error('Invalid guidance selection');
  return {passageIds:response.passageIds as string[],matches:validateMedicineMatches(response.matches,options)};
}

export function validateMedicineMatches(input:unknown,options:MatchSuggestions) {
  if(!Array.isArray(input)||input.length>options.length)throw new Error('Invalid medicine matches');
  const matches=new Map<number,string>();
  for(const match of input){
    if(!match||Object.keys(match).sort().join(',')!=='id,index'||!Number.isInteger(match.index)||
      matches.has(match.index)||!options.find(option=>option.index===match.index)?.ids.includes(match.id))throw new Error('Invalid medicine match');
    matches.set(match.index,match.id);
  }
  return matches;
}

export function validateCheckSynthesis(takeaway:unknown,nextAction:unknown,reported?:{
  prescribed:boolean;
  assessment?:'yes'|'no'|'unsure';
  reason:string;
}):NonNullable<CheckGuidance['synthesis']>{
  const prohibited=[
    /\b(?:\d+\s*(?:mg|ml|grams?|tablets?|capsules?|times?)|dosage|safe to (?:take|use)|safe (?:antibiotics?|options?))\b/i,
    /\b(?:you|we) (?:can|could|should|must|ought to|need to|may) (?:(?:not|never) )?(?:take|use|start|stop|switch|double|skip|avoid)\b/i,
    /(?:^|[.!?] )\s*(?:do not |don['’]t |never )?(?:take|use|start|stop|switch|double|skip|avoid)\b/i,
    /\b(?:you (?:have|do not have|don['’]t have|probably have)|you['’]re|you are) (?:[^.!?;]{0,36} )?(?:allergy|allergies|allergic)\b/i,
    /https?:|[<>\r\n]/i
  ];
  if(typeof takeaway!=='string'||(nextAction!==undefined&&typeof nextAction!=='string'))throw new Error('Invalid synthesis');
  const summary=takeaway.trim();
  const action=nextAction?.trim();
  if(summary.length<20||summary.length>520||prohibited.some(pattern=>pattern.test(summary)))throw new Error('Invalid synthesis');
  if(action!==undefined&&(action.length<12||action.length>180||!/^(?:Ask|Tell|Show|Bring|Share)\b/i.test(action)||
    prohibited.some(pattern=>pattern.test(action))))throw new Error('Invalid next action');
  if(reported){
    const text=summary+(action?' '+action:'');
    const history=/\b(?:was|were|is|been|has|have|had)(?:n['’]t)?\s+(?:(?:already|not|never|yet|previously|been)\s+)*(?:prescribed|assessed|examined|evaluated|checked)\b|\bdid(?:n['’]t)?\s+(?:not\s+)?(?:prescribe|assess|examine|evaluate|check)\b/i;
    if(!reported.prescribed&&/\b(?:your|the)\s+(?:prescriber|prescribing doctor|prescribing clinician)\b/i.test(text))
      throw new Error('Synthesis assumes a prescriber');
    if(history.test(text))throw new Error('Synthesis restates reported clinical history');
    if((reported.prescribed||reported.assessment==='yes')&&/\b(?:assess|evaluat|examin|diagnos)\w*\b/i.test(text))
      throw new Error('Synthesis asks for a new assessment');
    const topics=suggestReasons(reported.reason);
    if(topics.includes('boil')&&!topics.includes('skin')&&/\bwounds?\b/i.test(text))
      throw new Error('Synthesis recasts a boil as a wound');
  }
  return {takeaway:summary,...(action?{nextAction:action}:{})};
}

import type {GuidanceContext} from '@/lib/check-guidance';
import type {Medicine} from '@/lib/safety';

export type FollowUpAnswer='yes'|'no'|'unsure';
export type FollowUpAnswers=Record<string,FollowUpAnswer>;
export type FollowUpDetails=Record<string,string>;
export const followUpDetailLimit=240;
export type FollowUpQuestion={
 id:string;
 text:string;
 mandatory:boolean;
 detailPrompt?:string;
 concernOnYes?:boolean;
 source:{name:string;url:string};
};

const who={name:'WHO · 5 Moments for Medication Safety',url:'https://www.who.int/publications/i/item/WHO-HIS-SDS-2019.6'};
const euroclox={
 name:'NAFDAC Greenbook · Euroclox-500, section 4.3',
 url:'https://admin.greenbook.nafdac.gov.ng/uploadImage/smpc_files/2023/10/02/2023100254627596-886a-56ef-84c2-4303afc55ae6.pdf'
};
const ciprovam={name:'NAFDAC Greenbook · Ciprovam product information, section 4.4',url:'https://admin.greenbook.nafdac.gov.ng/uploadImage/smpc_files/2025/01/07/2025010755c585d3-8351-5f2f-ba64-dcad70462399.pdf'};
const ibuprofen={name:'NHS · Who can and cannot take ibuprofen',url:'https://www.nhs.uk/medicines/ibuprofen-for-adults/'};
const paracetamol={name:'NHS · Taking paracetamol with other medicines',url:'https://www.nhs.uk/medicines/paracetamol-for-adults/taking-paracetamol-for-adults-with-other-medicines-and-herbal-supplements/'};
const penicillins=['amoxicillin','ampicillin','cloxacillin','flucloxacillin','phenoxymethylpenicillin'];

export function availableFollowUps(medicine:Medicine,context:GuidanceContext):FollowUpQuestion[]{
 const penicillin=medicine.ingredients.some(ingredient=>penicillins.includes(ingredient));
 const ibuprofenCheck=medicine.id==='ibuprofen';
 return [
  penicillin?{
   id:'penicillin-reaction',text:'Have you ever had an allergic reaction to penicillin or a penicillin-type antibiotic?',
   mandatory:true,detailPrompt:'What happened?',concernOnYes:true,source:euroclox
  }:{
   id:'prior-reaction',text:'Have you ever had an allergic reaction to this medicine or one of its ingredients?',
   mandatory:true,detailPrompt:'What happened?',concernOnYes:true,source:who
  },
  ...(medicine.id==='co-amoxiclav'?[{
   id:'co-amoxiclav-liver-reaction',text:'After taking co-amoxiclav, did your skin or eyes turn yellow, or were you told it caused liver problems?',
   mandatory:true,concernOnYes:true,source:{name:'NAFDAC Greenbook · Co-amoxiclav product information, section 4.3',url:'https://admin.greenbook.nafdac.gov.ng/uploadImage/smpc_files/2024/09/16/202409168dbda631-b788-59cd-b794-17c96b430497.pdf'}
  }]:[]),
  ...(medicine.id==='ciprofloxacin'?[
   {id:'cipro-child',text:'Is this medicine for someone under 18?',mandatory:true,concernOnYes:true,source:ciprovam},
   {id:'cipro-tendon',text:'Have you had a tendon problem after taking ciprofloxacin or a similar antibiotic?',mandatory:true,concernOnYes:true,source:ciprovam}
  ]:[]),
  ...(ibuprofenCheck?[
   {id:'stomach-ulcer',text:'Have you ever had a stomach ulcer?',mandatory:true,concernOnYes:true,source:ibuprofen},
   {id:'asthma',text:'Do you have asthma?',mandatory:false,concernOnYes:true,source:ibuprofen},
   {id:'kidney-or-liver',text:'Do you have a kidney or liver condition?',mandatory:false,detailPrompt:'What condition do you have?',concernOnYes:true,source:ibuprofen}
  ]:[]),
  ...(medicine.id==='paracetamol'&&(context.otherMedicines.length||context.namesIncomplete)?[
   {id:'paracetamol-overlap',text:'Does any other medicine you take also contain paracetamol?',mandatory:true,detailPrompt:'What is the name on that pack?',concernOnYes:true,source:paracetamol}
  ]:[]),
  {id:'long-term-condition',text:'Do you have a long-term health condition?',mandatory:false,detailPrompt:'What condition do you have?',source:who},
  ...(ibuprofenCheck?[
   {id:'pregnancy',text:'Are you pregnant or trying to get pregnant?',mandatory:false,concernOnYes:true,source:ibuprofen}
  ]:[]),
  ...(!context.prescribed&&context.reason?[{
   id:'reason-assessed',text:'Has a doctor or pharmacist already checked the reason you want to take this medicine?',
   mandatory:false,source:who
  }]:[])
 ];
}

export function modelFollowUps(available:FollowUpQuestion[]){
 return available.filter(question=>!question.mandatory&&question.id!=='reason-assessed');
}

export function selectFollowUps(available:FollowUpQuestion[],ids:unknown):FollowUpQuestion[]{
 const choices=modelFollowUps(available);
 if(!Array.isArray(ids)||ids.length>2||new Set(ids).size!==ids.length||
  !ids.every(id=>choices.some(question=>question.id===id)))throw new Error('Invalid follow-up selection');
 return [...available.filter(question=>question.mandatory||question.id==='reason-assessed'),
  ...ids.map(id=>choices.find(question=>question.id===id)!)];
}

export function parseFollowUpAnswers(input:unknown,available:FollowUpQuestion[]):FollowUpAnswers|null{
 if(!input||typeof input!=='object'||Array.isArray(input))return null;
 const entries=Object.entries(input);
 if(!entries.every(([id,value])=>available.some(question=>question.id===id)&&(value==='yes'||value==='no'||value==='unsure'))||
  available.some(question=>question.mandatory&&!Object.hasOwn(input,question.id)))return null;
 return Object.fromEntries(entries);
}

export function parseFollowUpDetails(input:unknown,available:FollowUpQuestion[],answers:FollowUpAnswers):FollowUpDetails|null{
 if(!input||typeof input!=='object'||Array.isArray(input))return null;
 const entries=Object.entries(input);
 if(!entries.every(([id,value])=>answers[id]==='yes'&&available.some(question=>question.id===id&&question.detailPrompt)&&
  typeof value==='string'&&value.length<=followUpDetailLimit))return null;
 return Object.fromEntries(entries.map(([id,value])=>[id,(value as string).trim()]).filter(([,value])=>value));
}

import type {FollowUpAnswers,FollowUpQuestion} from '@/lib/check-follow-ups';

type CheckGap=
 |{kind:'unanswered'|'unsure';question:string}
 |{kind:'reason_missing'|'reason_evidence'|'other_medicines'|'condition'|'assessment'};

export function checkResult({prescribed,reason,questions,answers,interactions,needsInteractionReview,needsReasonReview}:{
 prescribed:boolean;
 reason:string;
 questions:FollowUpQuestion[];
 answers:FollowUpAnswers;
 interactions:boolean;
 needsInteractionReview:boolean;
 needsReasonReview:boolean;
}){
 const reportedConcern=questions.some(question=>question.concernOnYes&&answers[question.id]==='yes');
 const assessment=answers['reason-assessed'];
 const gaps:CheckGap[]=[];
 if(!reason.trim())gaps.push({kind:'reason_missing'});
 else if(needsReasonReview)gaps.push({kind:'reason_evidence'});
 if(needsInteractionReview)gaps.push({kind:'other_medicines'});
 if(!prescribed&&assessment==='no')gaps.push({kind:'assessment'});
 if(answers['long-term-condition']==='yes')gaps.push({kind:'condition'});
 for(const question of questions){
  if(answers[question.id]==='unsure')gaps.push({kind:'unsure',question:question.text});
  else if(question.mandatory&&!answers[question.id])gaps.push({kind:'unanswered',question:question.text});
 }
 const status=reportedConcern||interactions?'concern':gaps.length?'more_information':'no_concern';
 const clinician=prescribed?'prescriber':assessment==='yes'?'previous_clinician':
  (!reason.trim()&&!reportedConcern&&(interactions||needsInteractionReview))?'pharmacist':'doctor';
 return {status,clinician,assessment,gaps} as const;
}

import {normalizeIngredient} from '@/lib/safety';

export type GreenbookRecord={
 name:string;
 number:string;
 ingredients:string;
 strength:string;
 manufacturer:string;
 status:string;
 url:string;
};
export type GreenbookLookup=
 |{status:'found';record:GreenbookRecord;checked?:string}
 |{status:'not_found'|'unavailable'|'ambiguous'};

export function registrationNumber(input:unknown):string|null{
 if(typeof input!=='string'||input.length>40)return null;
 const value=input.trim().toUpperCase().replace(/[‐‑–—]/g,'-').replace(/\s*-\s*/g,'-');
 return /^(?=(?:.*\d){3})[A-Z0-9]{2,12}(?:-[A-Z0-9]{2,12}){0,2}$/.test(value)?value:null;
}

export function compareRegisteredIngredients(confirmed:readonly string[],registered:string){
 const parts=registered.replace(/\([^()]*\)/g,'').trim().split(/\s*[;+]\s*/).map(normalizeIngredient);
 // A comma or compound wording can conceal a longer list. Require a readable full list for comparison.
 if(!confirmed.length||!parts.length||parts.some(part=>!/^[a-z][a-z -]*$/i.test(part)||/\b(?:and|with)\b/i.test(part))||
   new Set(parts).size!==parts.length)return 'unconfirmed';
 return parts.length===confirmed.length&&parts.every(part=>confirmed.includes(part))?'match':'mismatch';
}

import saved from '@/data/greenbook-records.json';
import {nigeriaProducts} from '@/lib/safety';
import {registrationNumber,type GreenbookLookup,type GreenbookRecord} from '@/lib/greenbook';

const origin='https://greenbook.nafdac.gov.ng';
const columns=['product_name','ingredient.ingredient_name','product_category.name','product_category_id','ingredient.synonym','NAFDAC','form.name','route.name','strength','applicant.name','approval_date','status'];

export function greenbookSearch(number:string){
 const url=new URL('/',origin);
 const query=new URLSearchParams({draw:'1',start:'0',length:'12','search[value]':number,'search[regex]':'false',
  'order[0][column]':'0','order[0][dir]':'asc',search_ingredient:''});
 columns.forEach((name,index)=>{
  const column='columns['+index+']';
  query.set(column+'[data]',name);
  query.set(column+'[name]',name);
  query.set(column+'[searchable]','true');
  query.set(column+'[orderable]',String(index!==2));
  query.set(column+'[search][value]','');
  query.set(column+'[search][regex]','false');
 });
 url.search=query.toString();
 return url;
}

const entities:Record<string,string>={amp:'&',nbsp:' ',quot:'"',apos:"'",lt:'<',gt:'>'};
function plain(value:unknown){
 if(typeof value!=='string')return '';
 return value.replace(/<[^>]*>/g,' ').replace(/&(#\d+|#x[\da-f]+|[a-z]+);/gi,(_entity,key:string)=>{
  if(!key.startsWith('#'))return entities[key.toLowerCase()]??' ';
  const code=key[1]?.toLowerCase()==='x'?Number.parseInt(key.slice(2),16):Number(key.slice(1));
  return code>0&&code<=0x10ffff?String.fromCodePoint(code):' ';
 }).replace(/\s+/g,' ').replace(/[*#]/g,'').trim().slice(0,300);
}

export function parseGreenbookDetails(html:string,expected:string,url:string):GreenbookRecord|null{
 const heading=html.match(/<div class="card-body"[^>]*>\s*<h1>([^<]+)<\/h1>\s*<span>(.*?)<\/span>\s*<br\s*\/?>\s*<span>(.*?)<\/span>/is);
 const field=(label:string)=>plain(html.match(new RegExp('<h1[^>]*>\\s*'+label+'\\s*</h1>\\s*<p[^>]*>(.*?)</p>','is'))?.[1]);
 const number=registrationNumber(field('NRN'));
 const status=field('Status');
 const name=plain(heading?.[1]);
 if(number!==expected||!name||!status)return null;
 return {number,name,status,url,ingredients:plain(heading?.[2]),strength:plain(heading?.[3]),manufacturer:field('Manufacturer Name')};
}

async function requestGreenbook(url:string,accept:string,signal:AbortSignal,ajax=false){
 const headers:Record<string,string>={Accept:accept,'Cache-Control':'no-cache'};
 if(ajax)headers['X-Requested-With']='XMLHttpRequest';
 let target=new URL(url,origin);
 for(let redirects=0;redirects<=2;redirects++){
  if(target.origin!==origin||target.username||target.password)throw new Error('registry_redirect');
  const response=await fetch(target.href,{headers,redirect:'manual',signal});
  if(![301,302,303,307,308].includes(response.status))return response;
  const location=response.headers.get('location');
  if(!location)throw new Error('registry_redirect');
  await response.body?.cancel();
  target=new URL(location,target);
 }
 throw new Error('registry_redirect');
}

function registryFailure(error:unknown){
 if(!(error instanceof Error))return 'unknown_error';
 const message=error.message;
 if(error.name==='TimeoutError'||error.name==='AbortError')return 'timeout';
 if(message==='registry_redirect')return message;
 if(/certificate|ssl|tls/i.test(message))return 'tls';
 if(/dns|resolv/i.test(message))return 'dns';
 if(/egress|allowlist|disallow|restricted|prohibited|not allowed|blocked/i.test(message))return 'egress';
 if(/unsupported|not implemented|unrecognized|invalid option/i.test(message))return 'request_options';
 return error.name;
}

async function details(url:string,number:string,signal:AbortSignal){
 try{
  const response=await requestGreenbook(url,'text/html',signal);
  if(!response.ok){
   console.warn('Greenbook record request returned HTTP '+response.status);
   return null;
  }
  return parseGreenbookDetails(await response.text(),number,url);
 }catch(error){
  console.warn('Greenbook record request failed:',registryFailure(error));
  return null;
 }
}

async function liveGreenbookLookup(number:string):Promise<GreenbookLookup>{
 const signal=AbortSignal.timeout(9_000);
 const known=nigeriaProducts.find(product=>product.number===number);
 if(known){
  const record=await details(known.url,number,signal);
  if(record)return {status:'found',record};
 }
 try{
  const response=await requestGreenbook(greenbookSearch(number).href,'application/json',signal,true);
  if(!response.ok){
   console.warn('Greenbook search returned HTTP '+response.status);
   return {status:'unavailable'};
  }
  const payload=await response.json();
  if(!Array.isArray(payload?.data)||!Number.isInteger(payload.recordsFiltered)||payload.error)return {status:'unavailable'};
  const matches=payload.data.filter((row:Record<string,unknown>)=>row&&registrationNumber(row.NAFDAC)===number);
  if(matches.length===0)return {status:known?'unavailable':'not_found'};
  if(matches.length!==1||payload.recordsFiltered>payload.data.length)return {status:'ambiguous'};
  const row=matches[0];
  const id=String(row.product_id);
  const name=plain(row.product_name);
  const status=plain(row.status);
  if(!/^\d{1,12}$/.test(id)||!name||!status)return {status:'unavailable'};
  const url=origin+'/products/details/'+id;
  const record=await details(url,number,signal);
  return {status:'found',record:record??{
   name,number,status,url,ingredients:plain(row.ingredient?.ingredient_name),strength:plain(row.strength),manufacturer:''
  }};
 }catch(error){
  console.warn('Greenbook search failed:',registryFailure(error));
  return {status:'unavailable'};
 }
}

export async function lookUpGreenbook(number:string):Promise<GreenbookLookup>{
 const live=await liveGreenbookLookup(number);
 if(live.status==='found'||live.status==='ambiguous')return live;
 const record=saved.products.find(item=>item.number===number);
 return record?{status:'found',record,checked:saved.checked}:live;
}

import {allow,readBody,sameOrigin} from '@/lib/guard';
import {registrationNumber} from '@/lib/greenbook';
import {lookUpGreenbook} from '@/lib/greenbook-source';

export const runtime='nodejs';
export const maxDuration=15;

const headers={'Cache-Control':'no-store'};

export async function POST(request:Request){
 if(!sameOrigin(request))return Response.json({status:'unavailable'},{status:403,headers});
 const caller=request.headers.get('x-forwarded-for')?.split(',')[0]??'local';
 if(!allow('greenbook:'+caller))return Response.json({status:'unavailable'},{status:429,headers});
 const body=await readBody(request).catch(()=>null);
 const number=registrationNumber(body?.number);
 if(!number)return Response.json({status:'invalid'},{status:400,headers});
 return Response.json(await lookUpGreenbook(number),{headers});
}

'use client';

import {useEffect,useRef,useState} from 'react';
import {ChevronDown,Search} from 'lucide-react';
import {compareRegisteredIngredients,registrationNumber,type GreenbookLookup} from '@/lib/greenbook';
import PackPhoto from './PackPhoto';

export default function GreenbookCheck({ingredients,suggestedNumber,aiAvailable}:{
 ingredients:readonly string[];
 suggestedNumber?:string|null;
 aiAvailable:boolean;
}){
 const [input,setInput]=useState(suggestedNumber??'');
 const [lookup,setLookup]=useState<GreenbookLookup|null>(null);
 const [busy,setBusy]=useState(false);
 const [photo,setPhoto]=useState(false);
 const current=useRef<AbortController|null>(null);
 const number=registrationNumber(input);
 useEffect(()=>()=>current.current?.abort(),[]);

 function changeNumber(value:string){
  current.current?.abort();current.current=null;
  setBusy(false);setLookup(null);setInput(value);
 }
 async function check(){
  if(!number||busy)return;
  const controller=new AbortController();
  current.current=controller;
  const timeout=setTimeout(()=>controller.abort(),14_000);
  setBusy(true);setLookup(null);
  try{
   const response=await fetch('/api/greenbook',{
    method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({number}),signal:controller.signal
   });
   const result=await response.json() as GreenbookLookup;
   if(current.current===controller)setLookup(response.ok?result:{status:'unavailable'});
  }catch{
   if(current.current===controller)setLookup({status:'unavailable'});
  }finally{
   clearTimeout(timeout);
   if(current.current===controller){current.current=null;setBusy(false);}
  }
 }
 const record=lookup?.status==='found'?lookup.record:null;
 const comparison=record?compareRegisteredIngredients(ingredients,record.ingredients):null;

 return <details className="answer-sources" id="registration-check">
  <summary>Check NAFDAC registration<ChevronDown size={20} aria-hidden="true" className="answer-chevron"/></summary>
  <div className="answer-expanded registration-check">
   {suggestedNumber&&<p>Check that the number read from the photo matches the one on your pack.</p>}
   <form onSubmit={event=>{event.preventDefault();void check();}}>
    <label className="check-questions-field"><span>NAFDAC registration number</span>
     <input value={input} maxLength={40} placeholder="For example, A4-8312" autoComplete="off" autoCapitalize="characters"
      onChange={event=>changeNumber(event.target.value)}/>
    </label>
    <button type="submit" className="primary" disabled={!number||busy}><Search size={18} aria-hidden="true"/> Look up registration</button>
   </form>
   {aiAvailable&&!photo&&<button type="button" className="text-button" onClick={()=>setPhoto(true)}>Scan the number on the pack</button>}
   {photo&&<PackPhoto mode="registration" onClose={()=>setPhoto(false)} onRead={value=>{changeNumber(value);setPhoto(false);}}/>}
   {busy&&<p role="status">Looking in the NAFDAC Greenbook…</p>}
   {record&&<div aria-live="polite">
    <h3>{record.name}</h3>
    {lookup?.status==='found'&&lookup.checked&&<p>Saved Greenbook record checked on {lookup.checked}. The latest status could not be verified.</p>}
    <dl className="answer-medicine-record">
     <dt>NAFDAC number</dt><dd>{record.number}</dd>
     <dt>Registration status</dt><dd>{record.status}</dd>
     {record.ingredients&&<><dt>Active ingredients</dt><dd>{record.ingredients}</dd></>}
     {record.strength&&<><dt>Strength</dt><dd>{record.strength}</dd></>}
     {record.manufacturer&&<><dt>Manufacturer</dt><dd>{record.manufacturer}</dd></>}
    </dl>
    <p>{comparison==='match'?'The listed ingredients match those you confirmed. Compare the name and strength with your pack.':
     comparison==='mismatch'?'The listed ingredients differ from those you confirmed. Recheck the number and the pack with a pharmacist.':
     'Compare the ingredients, name, and strength with your pack.'}</p>
    <a href={record.url} target="_blank" rel="noreferrer">Source · NAFDAC Greenbook ↗</a>
   </div>}
   {lookup?.status==='not_found'&&<p role="status">The Greenbook search returned no exact match. Check the number on the pack. Some records may be missing from the search.</p>}
   {lookup?.status==='ambiguous'&&<p role="status">The Greenbook returned more than one possible record. Ask a pharmacist to compare the pack.</p>}
   {lookup?.status==='unavailable'&&<p role="status">The Greenbook lookup is unavailable right now. You can try again.</p>}
   <p className="next-steps-note">The Greenbook checks product registration. Confirming an individual pack requires a separate check.</p>
  </div>
 </details>;
}

'use client';

import {useCallback,useEffect,useRef,useState} from 'react';
import {Camera,ImageUp} from 'lucide-react';
import {fullPhotoCrop,prepareImage,type PhotoCrop} from '@/lib/image';
import {registrationNumber} from '@/lib/greenbook';
import type {ScanResult} from '@/lib/scan';
import CameraCapture from './CameraCapture';
import PhotoEditor from './PhotoEditor';

type Props={onClose:()=>void}&(
 {mode:'registration';onRead:(number:string)=>void}|
 {mode:'companion';onRead:(ingredients:string[])=>void}
);
type Photo={file:File;original:string;prepared:string;crop:PhotoCrop};

export default function PackPhoto(props:Props){
 const {mode,onClose}=props;
 const registration=mode==='registration';
 const [camera,setCamera]=useState(false);
 const closeCamera=useCallback(()=>setCamera(false),[]);
 const [photo,setPhoto]=useState<Photo|null>(null);
 const [cropOpen,setCropOpen]=useState(false);
 const [ingredients,setIngredients]=useState<string[]>([]);
 const [consent,setConsent]=useState(false);
 const [busy,setBusy]=useState(false);
 const [error,setError]=useState('');
 const revision=useRef(0);
 const request=useRef<AbortController|null>(null);
 const photoInput=useRef<HTMLInputElement>(null);
 const cameraInput=useRef<HTMLInputElement>(null);
 useEffect(()=>()=>{
  revision.current++;
  request.current?.abort();
 },[]);

 async function prepare(file:File,crop:PhotoCrop=fullPhotoCrop){
  request.current?.abort();
  const id=++revision.current;
  setBusy(true);setConsent(false);setError('');setIngredients([]);
  try{
   const prepared=await prepareImage(file,crop);
   if(id===revision.current)setPhoto({file,prepared,crop,original:photo?.file===file?photo.original:prepared});
  }catch(err){
   if(id===revision.current)setError(err instanceof Error?err.message:'We could not open this photo.');
  }finally{
   if(id===revision.current)setBusy(false);
  }
 }
 async function read(){
  if(!photo||!consent||busy)return;
  const controller=new AbortController();
  request.current=controller;
  const timeout=setTimeout(()=>controller.abort(),24_000);
  const id=++revision.current;
  setBusy(true);setError('');setIngredients([]);
  try{
   const response=await fetch('/api/scan',{
    method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,image:photo.prepared}),signal:controller.signal
   });
   const result=await response.json() as ScanResult&{registrationNumber?:string|null};
   if(id!==revision.current)return;
   if(registration&&props.mode==='registration'){
    const number=registrationNumber(result.registrationNumber);
    if(number){props.onRead(number);return;}
    setError('We could not read a full NAFDAC number. Try another photo or type the number.');
   }else if(result.observation?.complete&&result.observation.legibility==='clear'&&
     result.observation.productType==='medicine'&&result.observation.ingredients.length){
    setIngredients(result.observation.ingredients);
   }else setError('We could not read the full ingredient list. Try another photo or type the name on the pack.');
  }catch{
   if(id===revision.current)setError('The scan could not finish. Try again or type the details.');
  }finally{
   clearTimeout(timeout);
   if(id===revision.current)setBusy(false);
  }
 }
 return <div className="pack-photo">
  <input ref={photoInput} className="hidden" type="file" accept="image/jpeg,image/png,image/webp"
   onChange={event=>{const file=event.target.files?.[0];event.target.value='';if(file)void prepare(file);}}/>
  <input ref={cameraInput} className="hidden" type="file" accept="image/*" capture="environment"
   onChange={event=>{const file=event.target.files?.[0];event.target.value='';if(file)void prepare(file);}}/>
  <p>{registration?'Photograph the number marked NAFDAC or NRN.':'Photograph the full active ingredient list on the other pack.'}</p>
  {photo&&<img className="pack-photo-preview" src={photo.prepared} alt="Photo to scan"/>}
  {ingredients.length>0&&props.mode==='companion'?<div>
   <p>Does this match the full active ingredient list on your pack?</p>
   <ul>{ingredients.map(item=><li key={item}>{item}</li>)}</ul>
   <button type="button" className="primary" onClick={()=>props.onRead(ingredients)}>Use these ingredients</button>
  </div>:<>
   <div className="pack-photo-controls">
    <button type="button" disabled={busy} className="secondary" onClick={()=>setCamera(true)}><Camera size={18} aria-hidden="true"/> Take photo</button>
    <button type="button" disabled={busy} className="secondary" onClick={()=>photoInput.current?.click()}><ImageUp size={18} aria-hidden="true"/> Upload photo</button>
    {photo&&<button type="button" disabled={busy} className="secondary" onClick={()=>setCropOpen(true)}>Crop and zoom</button>}
   </div>
   {photo&&<><label className="medicine-check-consent"><input type="checkbox" checked={consent} onChange={event=>setConsent(event.target.checked)}/>
    <span>I agree to send this photo to Groq to read the label.</span>
   </label><button type="button" className="primary" disabled={!consent||busy} onClick={()=>void read()}>{registration?'Read the number':'Read the ingredients'}</button></>}
  </>}
  {busy&&<p role="status">Getting the photo ready or reading it…</p>}
  {error&&<p role="alert">{error}</p>}
  <button type="button" className="text-button" onClick={onClose}>Cancel scan</button>
  {camera&&<CameraCapture registration={registration} onClose={closeCamera} onCapture={file=>void prepare(file)} onNative={()=>cameraInput.current?.click()}/>}
  {photo&&cropOpen&&<PhotoEditor image={photo.original} initialCrop={photo.crop} onClose={()=>setCropOpen(false)}
   onApply={crop=>{setCropOpen(false);void prepare(photo.file,crop);}}/>}
 </div>;
}

